<section class="metric-grid"><div class="metric"><span>Appointments today</span><strong><?= count($bookings) ?></strong><small><?= escape((new DateTimeImmutable($today))->format('l, j F')) ?></small></div><div class="metric"><span>Confirmed today</span><strong><?= count(array_filter($bookings,fn($b)=>$b['status']==='confirmed')) ?></strong><small>Ready for your clients</small></div><div class="metric"><span>Payments recorded</span><strong><?= money($paidRevenue) ?></strong><small>Today's paid appointments</small></div><div class="metric metric-action"><span>Reception shortcut</span><a class="admin-button" href="manual-booking.php">+ New booking</a><small>Phone customers and walk-ins</small></div></section>
<section class="admin-section"><div class="section-title"><div><p class="admin-eyebrow">TODAY'S SCHEDULE</p><h2>Appointments at a glance</h2></div><a href="bookings.php?date=<?= $today ?>">Open calendar →</a></div><?php if (!$bookings): ?><div class="admin-empty"><h3>A clear day.</h3><p>No appointments are booked for today.</p></div><?php else: ?><div class="schedule-list"><?php foreach ($bookings as $booking): $time=(new DateTimeImmutable($booking['slot_start'],new DateTimeZone('UTC')))->setTimezone(business_timezone()); ?><a class="schedule-row" href="bookings.php?id=<?= $booking['id'] ?>"><time><?= $time->format('g:i A') ?></time><span class="schedule-client"><strong><?= escape($booking['customer_name']) ?></strong><small><?= escape($booking['reference']) ?></small></span><span><?= escape($booking['service_name']) ?><small><?= escape($booking['staff_name']) ?></small></span><span class="status status-<?= escape($booking['status']) ?>"><?= escape(str_replace('_',' ',$booking['status'])) ?></span><span class="row-arrow">→</span></a><?php endforeach; ?></div><?php endif; ?></section>
<section class="admin-section"><div class="section-title"><div><p class="admin-eyebrow">COMING UP</p><h2>Next confirmed appointments</h2></div><a href="bookings.php?status=confirmed">All bookings →</a></div><div class="upcoming-grid"><?php foreach ($upcoming as $booking): $time=(new DateTimeImmutable($booking['slot_start'],new DateTimeZone('UTC')))->setTimezone(business_timezone()); ?><a href="bookings.php?id=<?= $booking['id'] ?>" class="upcoming-item"><time><?= $time->format('D, j M') ?><strong><?= $time->format('g:i A') ?></strong></time><span><?= escape($booking['customer_name']) ?><small><?= escape($booking['service_name']) ?></small></span></a><?php endforeach; ?></div></section>
